_STATE={0:{"selected":None},1:{"selected":None}}
_AGENTS={}

def _get(o,k,d=None):
    try:return o.get(k,d)
    except Exception:
        try:return getattr(o,k)
        except Exception:return d

def _load():
    global _AGENTS,_SPEC
    if _AGENTS:return
    _SPEC=json.loads(zlib.decompress(base64.b85decode(_MODEL_B85)).decode())
    for seat in (0,1):
        _AGENTS[seat]={}
        for name,blob in _SOURCES.items():
            ns={};src=zlib.decompress(base64.b85decode(blob)).decode()
            exec(compile(src,"<embedded-"+name+"-"+str(seat)+">","exec"),ns)
            fn=ns.get("agent")
            if not callable(fn):raise RuntimeError("missing agent "+name)
            _AGENTS[seat][name]=fn

def _call(fn,obs,configuration):
    try:
        try:r=fn(obs,configuration)
        except TypeError:r=fn(obs)
        return copy.deepcopy(r) if isinstance(r,dict) else {"farmer":["PASS"],"hands":[],"market":[]}
    except Exception:
        return {"farmer":["PASS"],"hands":[],"market":[]}

def _num_map(x):
    if not isinstance(x,dict):return {}
    out={}
    for k,v in x.items():
        try:out[str(k)]=float(v or 0)
        except Exception:out[str(k)]=0.0
    return out

def _farm(prefix,farm,out):
    farm=farm if isinstance(farm,dict) else {}
    out[prefix+".money"]=float(farm.get("money",0) or 0);hands=farm.get("hands",[]) or []
    out[prefix+".hands"]=float(len(hands));out[prefix+".hires_today"]=float(farm.get("hires_today",0) or 0);out[prefix+".lands"]=float(len(farm.get("unlocked_quadrants",[]) or []))
    ps=[farm.get("farmer")]+list(hands);xs=[];ys=[]
    for p in ps:
        if isinstance(p,(list,tuple)) and len(p)>=2:xs.append(float(p[0]));ys.append(float(p[1]))
    out[prefix+".pos_x_mean"]=sum(xs)/max(1,len(xs));out[prefix+".pos_y_mean"]=sum(ys)/max(1,len(ys));out[prefix+".pos_x_span"]=(max(xs)-min(xs)) if xs else 0.0;out[prefix+".pos_y_span"]=(max(ys)-min(ys)) if ys else 0.0
    counts={};ysum=watered=unwatered=fed=unfed=cared=uncared=fert=0.0
    for row in farm.get("tiles",[]) or []:
        for tile in row or []:
            if tile is None:key="EMPTY"
            elif tile=="LOCKED":key="LOCKED"
            elif isinstance(tile,dict):
                key=str(tile.get("kind") or "DICT");crop=tile.get("crop");animal=tile.get("animal")
                if crop:counts["CROP:"+str(crop)]=counts.get("CROP:"+str(crop),0)+1
                if animal:counts["ANIMAL:"+str(animal)]=counts.get("ANIMAL:"+str(animal),0)+1
                try:ysum+=float(tile.get("yield_units",0) or 0)
                except Exception:pass
                if key=="PLANT":
                    if tile.get("watered_today"):watered+=1
                    else:unwatered+=1
                if animal:
                    if tile.get("fed_today"):fed+=1
                    else:unfed+=1
                    if tile.get("cared_today"):cared+=1
                    else:uncared+=1
                    fert+=float(bool(tile.get("fertilizer_available")))
            else:key="OTHER"
            counts[key]=counts.get(key,0)+1
    for key in ("EMPTY","LOCKED","WEED","PLANT","COOP","PASTURE"):out[prefix+".tile."+key]=float(counts.get(key,0))
    for crop in ("WHEAT","CARROT","TOMATO","STRAWBERRY","MELON"):out[prefix+".crop."+crop]=float(counts.get("CROP:"+crop,0))
    for animal in ("GOOSE","COW","SHEEP"):out[prefix+".animal."+animal]=float(counts.get("ANIMAL:"+animal,0))
    out[prefix+".yield_sum"]=ysum;out[prefix+".watered"]=watered;out[prefix+".unwatered"]=unwatered;out[prefix+".fed"]=fed;out[prefix+".unfed"]=unfed;out[prefix+".cared"]=cared;out[prefix+".uncared"]=uncared;out[prefix+".fertilizer_available"]=fert

def _features(obs):
    pid=int(_get(obs,"player",0) or 0);farms=list(_get(obs,"farms",[]) or []);me=farms[pid] if pid<len(farms) else {};opp=farms[1-pid] if len(farms)>=2 else {}
    out={"seat":float(pid),"step":float(_get(obs,"step",0) or 0),"day":float(_get(obs,"day",0) or 0),"hour":float(_get(obs,"hour",0) or 0)};_farm("self",me,out);_farm("opp",opp,out)
    out["diff.money"]=out["self.money"]-out["opp.money"];out["diff.hands"]=out["self.hands"]-out["opp.hands"];out["diff.lands"]=out["self.lands"]-out["opp.lands"]
    market=_get(obs,"market",{}) or {};prices=_num_map(market.get("prices",{}) if isinstance(market,dict) else {});inventory=_num_map(market.get("inventory",{}) if isinstance(market,dict) else {})
    for item in ("WHEAT","CARROT","TOMATO","STRAWBERRY","MELON","EGG","MILK","WOOL","FERTILIZER"):out["price."+item]=prices.get(item,0.0);out["market_inventory."+item]=inventory.get(item,0.0)
    town=_get(obs,"town",{}) or {};shops=list(town.get("unlocked_shops",[]) or []) if isinstance(town,dict) else [];out["shop_count"]=float(len(shops))
    for shop in ("BAKERY","PIZZA_SHOP","BRUNCH_SPOT","YARN_STORE","ICE_CREAM_SHOP","PET_CAFE","SMOOTHIE_SHOP","FARMERS_MARKET"):out["shop."+shop]=float(shops.count(shop))
    private=_get(obs,"private",{}) or {};shed=_num_map(private.get("shed",{}) if isinstance(private,dict) else {});seeds=_num_map(private.get("seeds",{}) if isinstance(private,dict) else {});carried={}
    for inv in (private.get("inventories",[]) if isinstance(private,dict) else []) or []:
        for item,v in _num_map(inv).items():carried[item]=carried.get(item,0.0)+v
    for item in ("WHEAT","CARROT","TOMATO","STRAWBERRY","MELON","EGG","MILK","WOOL","FERTILIZER","GOOSE","COW","SHEEP"):out["shed."+item]=shed.get(item,0.0);out["carried."+item]=carried.get(item,0.0)
    for crop in ("WHEAT","CARROT","TOMATO","STRAWBERRY","MELON"):out["seed."+crop]=seeds.get(crop,0.0)
    return out

def _leaf(tree,x):
    node=0;left=tree["left"];right=tree["right"];feature=tree["feature"];threshold=tree["threshold"];leaves=tree["leaves"]
    while str(node) not in leaves:
        node=left[node] if x[feature[node]]<=threshold[node] else right[node]
    return leaves[str(node)]

def _predict(x):
    m=_SPEC["model"];kind=m["kind"]
    if kind=="constant":return int(m["candidate"])
    if kind=="forest_classifier":
        scores=[0.0]*len(_CANDIDATES);classes=m["classes"]
        for tree in m["trees"]:
            v=_leaf(tree,x);total=sum(v) or 1.0
            for i,c in enumerate(classes):scores[c]+=v[i]/total
        return max(range(len(scores)),key=lambda i:scores[i])
    scores=[0.0]*len(_CANDIDATES)
    for tree in m["trees"]:
        v=_leaf(tree,x)
        for i in range(len(scores)):scores[i]+=v[i]
    return max(range(len(scores)),key=lambda i:scores[i])

def agent(obs,configuration=None):
    _load();pid=int(_get(obs,"player",0) or 0);step=int(_get(obs,"step",0) or 0)
    if step==0:_STATE[pid]={"selected":None}
    actions={name:_call(_AGENTS[pid][name],obs,configuration) for name in _CANDIDATES if _STATE[pid]["selected"] is None}
    if _STATE[pid]["selected"] is not None:return _call(_AGENTS[pid][_STATE[pid]["selected"]],obs,configuration)
    decision=int(_SPEC["decision"])
    if step<decision:return actions["unseen_current"]
    f=_features(obs);x=[float(f.get(n,0.0)) for n in _SPEC["features"]];choice=_predict(x);name=_CANDIDATES[choice];_STATE[pid]["selected"]=name
    return actions[name]

_load()
